DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`TrainerId` int unsigned NOT NULL, `SpellId` int unsigned NOT NULL, `MoneyCost` int unsigned NOT NULL, `ReqSkillLine` int unsigned NOT NULL, `ReqSkillRank` int unsigned NOT NULL, `ReqAbility1` int unsigned NOT NULL, `ReqAbility2` int unsigned NOT NULL, `ReqAbility3` int unsigned NOT NULL, `ReqLevel` tinyint unsigned NOT NULL, `VerifiedBuild` int NOT NULL, `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`TrainerId`, `SpellId`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `everlake_import_stage` (`TrainerId`, `SpellId`, `MoneyCost`, `ReqSkillLine`, `ReqSkillRank`, `ReqAbility1`, `ReqAbility2`, `ReqAbility3`, `ReqLevel`, `VerifiedBuild`, `note`) VALUES
