UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `trainer_spell` t WHERE t.`TrainerId` = s.`TrainerId` AND t.`SpellId` = s.`SpellId`) AND EXISTS (SELECT 1 FROM `creature_trainer` l JOIN `creature_template` c ON c.`entry` = l.`CreatureId` JOIN `creature` g ON g.`id` = c.`entry` JOIN `trainer` t ON t.`Id` = l.`TrainerId` WHERE l.`TrainerId` = s.`TrainerId` AND t.`Type` = 2 AND (COALESCE(g.`npcflag`, c.`npcflag`) & 16) = 16 AND ((s.`TrainerId` = 36 AND s.`SpellId` = 2550 AND l.`CreatureId` = 8306) OR (s.`TrainerId` = 36 AND s.`SpellId` = 3102 AND l.`CreatureId` = 8306) OR (s.`TrainerId` = 37 AND s.`SpellId` = 2575 AND l.`CreatureId` = 3001) OR (s.`TrainerId` = 39 AND s.`SpellId` = 3273 AND l.`CreatureId` = 2798) OR (s.`TrainerId` = 113 AND s.`SpellId` = 8613 AND l.`CreatureId` = 6289))) AND NOT EXISTS (SELECT 1 FROM `everlake_import_rows` r WHERE r.`tbl` = 'trainer_spell' AND r.`k1` = s.`TrainerId` AND r.`k2` = s.`SpellId`);
INSERT INTO `trainer_spell` (`TrainerId`, `SpellId`, `MoneyCost`, `ReqSkillLine`, `ReqSkillRank`, `ReqAbility1`, `ReqAbility2`, `ReqAbility3`, `ReqLevel`, `VerifiedBuild`) SELECT `TrainerId`, `SpellId`, `MoneyCost`, `ReqSkillLine`, `ReqSkillRank`, `ReqAbility1`, `ReqAbility2`, `ReqAbility3`, `ReqLevel`, `VerifiedBuild` FROM `everlake_import_stage` WHERE `missing` = 1;
INSERT INTO `everlake_import_rows` (`tbl`, `k1`, `k2`, `file`, `note`) SELECT 'trainer_spell', s.`TrainerId`, s.`SpellId`, '2026_11_10_05_world_everlake_import_slice10.sql', s.`note` FROM `everlake_import_stage` s WHERE s.`missing` = 1 ON DUPLICATE KEY UPDATE `file` = '2026_11_10_05_world_everlake_import_slice10.sql', `note` = s.`note`;
